  function options(rows,label,selected){return rows.map(function(x){var v=typeof label==='function'?label(x):x[label];return '<option value="'+x.id+'"'+(x.id===selected?' selected':'')+'>'+esc(v)+'</option>';}).join('');}
  function dialog(html){var d=document.getElementById('inventory-dialog');d.removeAttribute('data-plain');d.innerHTML=html;d.showModal();var c=d.querySelector('[data-close]');if(c)c.onclick=function(){d.close();};return d;}
