  function incomingQuantity(x){var total=0;state.orderLines.forEach(function(l){if(l.item_id!==x.item_id)return;var o=by(state.orders,l.purchase_order_id);if(!o||!['ordered','partially_received'].includes(o.status)||o.destination_location_id!==x.location_id)return;total+=Math.max(0,Number(l.ordered_quantity||0)-Number(l.received_quantity||0));});return total;}
