    if(state.accessTenant===window.tenantId)return state.canConsume;
    try{var a=await window.sb.auth.getUser();state.actor=a.data&&a.data.user&&a.data.user.id;var access=await Promise.all([q(window.sb.from('smyl_role_permissions').select('role_id,permission_key').eq('tenant_id',window.tenantId)),q(window.sb.from('smyl_member_roles').select('user_id,role_id').eq('tenant_id',window.tenantId))]);state.rolePermissions=access[0]||[];state.memberRoles=access[1]||[];capabilities();state.accessTenant=window.tenantId;}catch(e){return false;}
