  function renderStock(){var host=document.getElementById('inventory-stock'),rows=state.snapshot.filter(function(x){return !state.location||x.location_id===state.location;}),search=(document.getElementById('inventory-search').value||'').toLowerCase();if(state.stockFilter==='attention')rows=rows.filter(function(x){return x.below_minimum||(x.days_to_expiry!=null&&Number(x.days_to_expiry)<=30&&Number(x.on_hand)>0);});if(state.stockFilter==='low')rows=rows.filter(function(x){return x.below_minimum;});if(state.stockFilter==='expiry')rows=rows.filter(function(x){return x.days_to_expiry!=null&&Number(x.days_to_expiry)<=30&&Number(x.on_hand)>0;});if(search)rows=rows.filter(function(x){return (x.item_name+' '+x.sku+' '+x.category).toLowerCase().includes(search);});document.querySelectorAll('[data-stock-filter]').forEach(function(b){b.setAttribute('aria-selected',String(b.dataset.stockFilter===state.stockFilter));});var firstUse=!state.items.length,panel=document.querySelector('[data-inventory-panel="stock"]');if(panel)panel.classList.toggle('inventory-first',firstUse);if(firstUse){renderFirstUse(host);return;}var toOrder=state.canPurchase?rowsToOrder():[],bar=toOrder.length&&state.stockFilter!=='expiry'?'<div class="inventory-suggest-bar"><div><b>'+toOrder.length+(toOrder.length===1?' insumo por reponer':' insumos por reponer')+'</b><span>Pedido sugerido según tus mínimos y lo que ya viene en camino</span></div><button type="button" class="btn btn-primary" data-suggest-orders>Crear pedidos sugeridos</button></div>':'';host.innerHTML=rows.length?bar+'<div class="inventory-table"><div class="inventory-row inventory-row-head"><span>Insumo</span><span>Ubicación</span><span>Existencia</span><span>Próxima caducidad</span><span>Control</span></div>'+rows.map(function(x){var expired=x.days_to_expiry!=null&&Number(x.days_to_expiry)<0,tone=expired?'expired':x.below_minimum?'low':x.days_to_expiry!=null&&x.days_to_expiry<=30?'expiry':'ok',suggested=suggestedPurchase(x),incoming=incomingQuantity(x);return '<article class="inventory-row" data-tone="'+tone+'"><div><strong>'+esc(x.item_name)+'</strong><small>'+esc(x.sku)+' · '+esc(x.category)+(x.requires_patient_trace?' · Trazabilidad por paciente':'')+'</small></div><span>'+esc(x.location_name)+'</span><div><strong>'+fmt(x.on_hand)+' '+esc(x.unit)+'</strong><small>'+(suggested?'Sugerido pedir '+fmt(suggested)+' · ':'')+(incoming?'En camino '+fmt(incoming)+' · ':'')+'Mínimo '+fmt(x.minimum_quantity)+'</small></div><span>'+(x.nearest_expiry?date(x.nearest_expiry)+(expired?' · Caducado':x.days_to_expiry<=30?' · '+x.days_to_expiry+' días':''):'Sin caducidad')+'</span><div><span class="inventory-badge" data-tone="'+tone+'">'+(expired?'No utilizar':x.below_minimum?'Reponer':tone==='expiry'?'Por caducar':'Disponible')+'</span>'+(state.canPurchase&&x.below_minimum&&suggested>0?'<button type="button" class="inventory-reponer" data-reponer="'+x.item_id+'" data-location="'+x.location_id+'">Reponer '+fmt(suggested)+'</button>':'')+(state.canManage?'<button data-reorder="'+x.item_id+'" data-location="'+x.location_id+'">Mínimos</button>':'')+'</div></article>';}).join('')+'</div>':(state.stockFilter==='attention'&&!search&&!state.location?'<div class="inventory-empty" data-good="true"><strong>Todo en orden</strong><p>Ningún insumo está bajo mínimo ni por caducar.</p><button type="button" class="btn btn-secondary" data-stock-all>Ver todo el inventario</button></div>':'<div class="inventory-empty"><strong>Sin resultados en este filtro</strong><p>Prueba otra ubicación, estado o término de búsqueda.</p></div>');var allBtn=host.querySelector('[data-stock-all]');if(allBtn)allBtn.onclick=function(){state.stockFilter='all';renderStock();};host.querySelectorAll('[data-reorder]').forEach(function(b){b.onclick=function(){openReorder(b.dataset.reorder,b.dataset.location);};});host.querySelectorAll('[data-reponer]').forEach(function(b){b.onclick=function(){var x=state.snapshot.find(function(r){return r.item_id===b.dataset.reponer&&r.location_id===b.dataset.location;});if(!x)return;openOrder({supplier:usualSupplier(x.item_id),destination:x.location_id,lines:[{item_id:x.item_id,quantity:suggestedPurchase(x)}]});};});var suggestBtn=host.querySelector('[data-suggest-orders]');if(suggestBtn)suggestBtn.onclick=openSuggestedOrders;}
  function renderMovements(){var h=document.getElementById('inventory-movements'),rows=state.movements.slice(0,100);h.innerHTML=rows.length?rows.map(function(m){var lines=state.movementLines.filter(function(l){return l.movement_id===m.id;}),src=by(state.locations,m.source_location_id),dst=by(state.locations,m.destination_location_id),reversed=state.movements.some(function(x){return x.reversal_of===m.id;});return '<article class="inventory-movement"><div class="inventory-movement-icon" data-type="'+m.movement_type+'">'+(m.movement_type==='transfer'?'↔':m.destination_location_id?'+':'−')+'</div><div><span>'+esc(TYPES[m.movement_type]||m.movement_type)+'</span><strong>'+lines.map(function(l){var i=by(state.items,l.item_id);return fmt(l.quantity)+' '+esc(i?i.unit:'')+' '+esc(i?i.name:'Insumo');}).join(' · ')+'</strong><small>'+date(m.occurred_at)+' · '+esc(src?src.name:'Origen externo')+(dst?' → '+esc(dst.name):'')+(m.patient_id?' · '+esc(patientName(m.patient_id)):'')+'</small><p>'+esc(m.reason)+'</p></div>'+(state.canAdjust&&!reversed&&m.movement_type!=='reversal'?'<button data-reverse="'+m.id+'">Corregir</button>':'')+'</article>';}).join(''):'<div class="inventory-empty"><strong>Aún no hay movimientos</strong><p>Las recepciones, consumos, traslados y mermas aparecerán aquí.</p></div>';h.querySelectorAll('[data-reverse]').forEach(function(b){b.onclick=function(){reverseMovement(b.dataset.reverse);};});}
