      form=d.querySelector('form'),host=form.querySelector('[data-order-lines]'),supplierSel=form.querySelector('select[name="supplier"]'),destSel=form.querySelector('select[name="destination"]'),err=form.querySelector('[data-order-error]'),box=form.querySelector('[data-supplier-box]');
    function fail(text){err.textContent=text||'';err.hidden=!text;}
