    function totals(){var lines=0,sum=0,missing=0;draft.forEach(function(l){if(l.item_id&&Number(l.quantity)>0){lines++;if(l.unit_cost!==''&&Number(l.unit_cost)>=0)sum+=Number(l.quantity)*Number(l.unit_cost);else missing++;}});form.querySelector('[data-total-lines]').textContent=lines+(lines===1?' insumo':' insumos')+(missing&&lines?' · '+missing+' sin costo':'');form.querySelector('[data-total-amount]').textContent=(sum?money(sum)+' estimado':'Sin costo estimado');}
    function missingItems(){var chosen=new Set(draft.map(function(l){return l.item_id;})),loc=destSel.value,seen={};return state.snapshot.filter(function(x){if(!x.below_minimum||chosen.has(x.item_id)||seen[x.item_id])return false;if(loc&&x.location_id!==loc)return false;seen[x.item_id]=1;return suggestedPurchase(x)>0;});}
