  function openReceive(order){var lines=state.orderLines.filter(function(x){return x.purchase_order_id===order.id&&Number(x.received_quantity)<Number(x.ordered_quantity);}),d=dialog('<form><h2>Recibir compra</h2><p>Confirma cantidades, lote y caducidad. Esta recepción generará una entrada inmutable.</p><div class="inventory-receive-lines">'+lines.map(function(l){var i=by(state.items,l.item_id),remaining=Number(l.ordered_quantity)-Number(l.received_quantity);return '<fieldset data-line="'+l.id+'"><legend>'+esc(i?i.name:'Insumo')+' · pendiente '+fmt(remaining)+'</legend><div class="inventory-form-grid"><label>Cantidad<input name="qty-'+l.id+'" type="number" min="0" max="'+remaining+'" step="0.001" value="'+remaining+'"></label>'+(i&&i.track_lot?'<label>Lote<input name="lot-'+l.id+'" maxlength="100" required></label>':'')+(i&&i.track_expiry?'<label>Caducidad<input name="expiry-'+l.id+'" type="date" required></label>':'')+(i&&i.track_serial?'<label>Serie<input name="serial-'+l.id+'" maxlength="140" required></label>':'')+'</div></fieldset>';}).join('')+'</div><div class="inventory-actions"><button type="button" class="btn btn-secondary" data-close>Cancelar</button><button class="btn btn-primary">Confirmar recepción</button></div></form>');d.querySelector('form').onsubmit=async function(e){e.preventDefault();var f=new FormData(e.currentTarget),payload=lines.map(function(l){var qty=Number(f.get('qty-'+l.id)||0);return qty>0?{line_id:l.id,quantity:qty,lot_code:f.get('lot-'+l.id)||'',expires_on:f.get('expiry-'+l.id)||null,serial_number:f.get('serial-'+l.id)||''}:null;}).filter(Boolean);if(!payload.length){notify('Captura al menos una cantidad recibida.','error');return;}try{await rpc('smyl_receive_purchase_order',{p_order_id:order.id,p_movement_id:crypto.randomUUID(),p_idempotency_key:crypto.randomUUID(),p_receipt_lines:payload});close();await reload('Compra recibida; existencias y lotes actualizados.');}catch(err){notify(error(err),'error');}};}
