  function build(){var page=el('section','pantalla inventory-page');page.id='p-inventario';page.innerHTML='<header class="inventory-head"><div><h1>Inventario</h1><p>Existencias, compras y consumo clínico con trazabilidad por ubicación, lote y paciente.</p></div><div class="inventory-head-actions"><button class="btn btn-secondary" id="inventory-new-order">Nueva compra</button><button class="btn btn-primary" id="inventory-new-movement">Registrar movimiento</button></div></header><div id="inventory-feedback" aria-live="polite"></div><div id="inventory-alerts" class="inventory-alerts"></div><nav class="inventory-tabs"><button data-inventory-tab="stock" aria-selected="true">Existencias</button><button data-inventory-tab="movements">Movimientos</button><button data-inventory-tab="orders">Compras</button><button data-inventory-tab="catalog">Catálogo y configuración</button></nav><section data-inventory-panel="stock"><div class="inventory-toolbar"><input id="inventory-search" type="search" placeholder="Buscar insumo o SKU"><select id="inventory-location" aria-label="Filtrar ubicación"></select></div><div class="inventory-stock-filters" role="group" aria-label="Filtrar existencias por estado"><button type="button" data-stock-filter="attention" aria-selected="true">Por atender</button><button type="button" data-stock-filter="low">Bajo mínimo</button><button type="button" data-stock-filter="expiry">Caducidad</button><button type="button" data-stock-filter="all">Todo</button></div><div id="inventory-stock"></div></section><section data-inventory-panel="movements" hidden><div class="inventory-section-title"><div><h2>Libro de movimientos</h2><p>Los confirmados no se editan; se corrigen mediante compensaciones.</p></div></div><div id="inventory-movements" class="inventory-movement-list"></div></section><section data-inventory-panel="orders" hidden><div class="inventory-section-title"><div><h2>Órdenes y recepciones</h2><p>La recepción actualiza lotes y existencias en una sola transacción.</p></div></div><div id="inventory-orders" class="inventory-order-list"></div></section><section data-inventory-panel="catalog" hidden><div class="inventory-catalog-grid"><article class="inventory-card inventory-catalog-wide"><div class="inventory-section-title"><div><h2>Insumos</h2><p>Materiales, medicamentos, implantes e instrumental.</p></div><button id="inventory-add-item">Agregar</button></div><div id="inventory-items" class="inventory-simple-list"></div></article><article class="inventory-card"><div class="inventory-section-title"><div><h2>Proveedores</h2></div><button id="inventory-add-supplier">Agregar</button></div><div id="inventory-suppliers" class="inventory-simple-list"></div></article><article class="inventory-card"><div class="inventory-section-title"><div><h2>Ubicaciones</h2></div><button id="inventory-add-location">Agregar</button></div><div id="inventory-locations" class="inventory-simple-list"></div></article></div></section><dialog id="inventory-dialog" class="inventory-dialog"></dialog><dialog id="inventory-confirm" class="inventory-dialog inventory-confirm"></dialog>';document.querySelector('.contenido').append(page);page.querySelectorAll('[data-inventory-tab]').forEach(function(b){b.onclick=function(){state.tab=b.dataset.inventoryTab;render();};});page.querySelectorAll('[data-stock-filter]').forEach(function(b){b.onclick=function(){state.stockFilter=b.dataset.stockFilter;renderStock();};});page.querySelector('#inventory-new-movement').onclick=openMovement;page.querySelector('#inventory-new-order').onclick=function(){openOrder();};page.querySelector('#inventory-add-item').onclick=openItem;page.querySelector('#inventory-add-supplier').onclick=openSupplier;page.querySelector('#inventory-add-location').onclick=openLocation;page.querySelector('#inventory-search').oninput=renderStock;page.querySelector('#inventory-location').onchange=function(){state.location=this.value;renderStock();};page.querySelector('#inventory-dialog').onclick=function(e){if(e.target===e.currentTarget)e.currentTarget.close();};}
  function navigation(){window.TITULOS.inventario='Inventario';var primary=document.querySelector('.pro-primary-nav');if(primary&&!primary.querySelector('[onclick="ir(\'inventario\')"]')){var b=el('button','nav-item','Inventario');b.type='button';b.setAttribute('onclick',"ir('inventario')");var agenda=primary.querySelector('[onclick="ir(\'agenda\')"]');if(agenda)agenda.after(b);else primary.append(b);}var mobile=document.querySelector('.pro-mobile-nav');if(mobile&&!mobile.querySelector('[onclick="ir(\'inventario\')"]')){var m=el('button','nav-item','Inventario');m.type='button';m.setAttribute('onclick',"ir('inventario')");var a=mobile.querySelector('[onclick="ir(\'agenda\')"]');if(a)a.after(m);else mobile.append(m);}}
  function init(){build();mountCosts();mountKits();navigation();window.addEventListener('smyl:appointment-completed',function(e){var app=e&&e.detail&&e.detail.appointment;if(app)suggestMaterialAfterClose(app);});var previous=window.ir;window.ir=function(route){var r=previous(route);if(route==='inventario'){var sel=document.getElementById('inventory-location');if(sel&&state.locations.length){sel.innerHTML='<option value="">Todas las ubicaciones</option>'+options(state.locations,'name',state.location);sel.value=state.location;}load(false).then(function(){var x=document.getElementById('inventory-location');if(x){x.innerHTML='<option value="">Todas las ubicaciones</option>'+options(state.locations,'name',state.location);x.value=state.location;}});}return r;};window.SmylInventory=Object.freeze({reload:function(){return reload();},consumptionStatus:consumptionStatus,openConsumption:function(context){window.ir('inventario');var attempts=0;function ready(){if(state.loaded&&!state.loading){if(!state.canConsume){notify('Tu rol puede consultar inventario, pero no registrar consumos.','error');return;}openKitConsumption(context||{});return;}if(attempts++<120)setTimeout(ready,50);else notify('No fue posible preparar el registro de materiales.','error');}ready();return true;}});}
  function enhanceSemantics(){var page=document.getElementById('p-inventario');if(!page)return;var tablist=page.querySelector('.inventory-tabs'),tabs=Array.from(page.querySelectorAll('[data-inventory-tab]')),panels=Array.from(page.querySelectorAll('[data-inventory-panel]'));if(tablist){tablist.setAttribute('role','tablist');tablist.setAttribute('aria-label','Secciones de inventario');}tabs.forEach(function(tab,index){var name=tab.dataset.inventoryTab,panel=panels.find(function(candidate){return candidate.dataset.inventoryPanel===name;});tab.id='inventory-tab-'+name;tab.setAttribute('role','tab');if(panel){panel.id='inventory-panel-'+name;tab.setAttribute('aria-controls',panel.id);panel.setAttribute('aria-labelledby',tab.id);}tab.onkeydown=function(event){var next=index;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();state.tab=tabs[next].dataset.inventoryTab;render();tabs[next].focus();};});panels.forEach(function(panel){panel.setAttribute('role','tabpanel');panel.setAttribute('tabindex','0');});}
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);document.addEventListener('DOMContentLoaded',enhanceSemantics);}else{init();enhanceSemantics();}
